```java
package com.example.starter.maintenance.domain;

import java.util.ArrayList;
import java.util.List;

/**
 * 负荷加权等效寿命计算：相邻累计读数增量按本次读数声明的负荷权重累计，
 * 首条以 0 为基准；全部为整数等效分钟。
 */
public final class EquivalentLife {

    private EquivalentLife() {
    }

    /** 按采样时刻升序的读数序列，计算每条读数对应的等效累计（前缀和）。 */
    public static List<Long> prefixTotals(List<Reading> readingsAsc) {
        List<Long> totals = new ArrayList<>(readingsAsc.size());
        long total = 0;
        long previousCumulative = 0;
        for (Reading reading : readingsAsc) {
            total += (reading.cumulativeMinutes() - previousCumulative) * reading.loadWeightFactor();
            totals.add(total);
            previousCumulative = reading.cumulativeMinutes();
        }
        return totals;
    }

    /** 最新（最后一条）读数的等效累计；无读数时为 0。 */
    public static long totalOf(List<Reading> readingsAsc) {
        List<Long> totals = prefixTotals(readingsAsc);
        return totals.isEmpty() ? 0L : totals.get(totals.size() - 1);
    }
}
```

