package com.example.starter.maintenance.domain;

/**
 * 负荷权重档位：相邻累计读数增量按本次读数声明的档位加权计入等效寿命。
 * NORMAL 权重 1，HEAVY 权重 2；历史旧读数一律按 NORMAL。
 */
public enum LoadWeight {

    NORMAL(1),
    HEAVY(2);

    private final int factor;

    LoadWeight(int factor) {
        this.factor = factor;
    }

    public int factor() {
        return factor;
    }

    /** 档位权重系数；空值或未知档位按 NORMAL（兼容历史旧读数）。 */
    public static int factorOf(String name) {
        if (name == null) {
            return NORMAL.factor;
        }
        for (LoadWeight weight : values()) {
            if (weight.name().equals(name)) {
                return weight.factor;
            }
        }
        return NORMAL.factor;
    }
}

package com.example.starter.maintenance.domain;

import java.util.ArrayList;
import java.util.List;

/**
 * 负荷加权等效寿命计算：按采样时刻升序，相邻累计读数增量乘以本次读数声明的
 * 负荷权重（NORMAL=1、HEAVY=2）累计，首条以 0 为基准；全部为整数等效分钟。
 * 等效累计完全由当前读数序列推导，读数更正后重算时它与后一条间隔的贡献同步变化。
 */
public final class EquivalentLife {

    private EquivalentLife() {
    }

    /** 计算每条读数对应的等效累计（前缀和），返回列表与入参读数序列一一对应。 */
    public static List<Long> prefixTotals(List<Reading> readingsAsc) {
        List<Long> totals = new ArrayList<>(readingsAsc.size());
        long total = 0;
        long previousCumulative = 0;
        for (Reading reading : readingsAsc) {
            total += (reading.cumulativeMinutes() - previousCumulative)
                    * LoadWeight.factorOf(reading.loadWeight());
            totals.add(total);
            previousCumulative = reading.cumulativeMinutes();
        }
        return totals;
    }

    /** 最新一条读数的等效累计；无读数时为 0。 */
    public static long totalOf(List<Reading> readingsAsc) {
        long total = 0;
        long previousCumulative = 0;
        for (Reading reading : readingsAsc) {
            total += (reading.cumulativeMinutes() - previousCumulative)
                    * LoadWeight.factorOf(reading.loadWeight());
            previousCumulative = reading.cumulativeMinutes();
        }
        return total;
    }
}

package com.example.starter.maintenance.domain;

/**
 * 设备。
 *
 * @param equipmentId               设备唯一标识
 * @param maintenancePeriodMinutes  物理保养周期（分钟），登记后不可修改
 * @param equivalentPeriodMinutes   等效寿命周期（等效分钟），正整数；null 表示未启用等效寿命口径
 * @param version                   设备版本号，初始 1，每次写操作校验并加一
